-- Generated by serving.py; no credentials. Run as warehouse administrator.
CREATE DATABASE IF NOT EXISTS `vatican_bi`;

CREATE OR REPLACE VIEW `vatican_bi`.`runs` SQL SECURITY DEFINER AS SELECT run_id, player_id, occurred_at, toDate(occurred_at) AS day,
            ruleset_id, content_release_id, outcome, church_level,
            hero_kills, tower_kills, building_upgrades,
            xp_granted, isNotNull(xp_granted) AS xp_known,
            toDecimal128(ifNull(xp_granted, 0), 0) AS known_xp
        FROM `vatican_analytics`.fact_run_settlements FINAL;

CREATE TABLE IF NOT EXISTS `vatican_bi`.`runs_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`occurred_at`) ORDER BY (`occurred_at`, `run_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`runs` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_runs` REFRESH EVERY 5 MINUTE OFFSET 0 SECOND TO `vatican_bi`.`runs_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`runs` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.`xp` SQL SECURITY DEFINER AS SELECT event_id, player_id, occurred_at, toDate(occurred_at) AS day,
            run_id, ruleset_id, source_type, level_after,
            toDecimal128(xp_delta, 0) AS xp_delta,
            toDecimal128(hero_kill_xp, 0) AS hero_xp,
            toDecimal128(tower_kill_xp, 0) AS tower_xp,
            toDecimal128(tycoon_upgrade_xp, 0) AS tycoon_xp,
            toDecimal128(victory_xp, 0) AS victory_xp
        FROM `vatican_analytics`.fact_xp_transactions FINAL;

CREATE TABLE IF NOT EXISTS `vatican_bi`.`xp_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`occurred_at`) ORDER BY (`occurred_at`, `event_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`xp` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_xp` REFRESH EVERY 5 MINUTE OFFSET 30 SECOND TO `vatican_bi`.`xp_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`xp` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.`level_ups` SQL SECURITY DEFINER AS SELECT event_id, player_id, occurred_at, toDate(occurred_at) AS day,
            run_id, old_level, new_level,
            toInt64(new_level) - toInt64(old_level) AS levels_gained
        FROM `vatican_analytics`.fact_player_level_ups FINAL;

CREATE TABLE IF NOT EXISTS `vatican_bi`.`level_ups_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`occurred_at`) ORDER BY (`occurred_at`, `event_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`level_ups` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_level_ups` REFRESH EVERY 5 MINUTE OFFSET 60 SECOND TO `vatican_bi`.`level_ups_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`level_ups` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.`level_gifts` SQL SECURITY DEFINER AS SELECT claim_id, player_id, assumeNotNull(claimed_at) AS occurred_at,
            toDate(claimed_at) AS day, rewarded_level, reward_bundle_id
        FROM `vatican_analytics`.fact_level_gift_claims FINAL
        WHERE claim_status = 'CLAIMED' AND claimed_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS `vatican_bi`.`level_gifts_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`occurred_at`) ORDER BY (`occurred_at`, `claim_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`level_gifts` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_level_gifts` REFRESH EVERY 5 MINUTE OFFSET 90 SECOND TO `vatican_bi`.`level_gifts_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`level_gifts` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.`case_openings` SQL SECURITY DEFINER AS SELECT opening_id, player_id, completed_at AS occurred_at, toDate(completed_at) AS day,
            case_code, ruleset_id, payment_mode, rarity, pity_before, pity_after,
            guaranteed_triggered, entry_index
        FROM `vatican_analytics`.fact_case_settlements FINAL;

CREATE TABLE IF NOT EXISTS `vatican_bi`.`case_openings_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`occurred_at`) ORDER BY (`occurred_at`, `opening_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`case_openings` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_case_openings` REFRESH EVERY 5 MINUTE OFFSET 120 SECOND TO `vatican_bi`.`case_openings_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`case_openings` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.`shop_purchases` SQL SECURITY DEFINER AS SELECT purchase_id, operation_id, player_id, completed_at AS occurred_at,
            toDate(completed_at) AS day, offer_id, catalog_version,
            currency_code, toDecimal128(charged_amount, 0) AS charged_amount,
            weapon_configuration_id
        FROM `vatican_analytics`.fact_shop_purchases FINAL;

CREATE TABLE IF NOT EXISTS `vatican_bi`.`shop_purchases_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`occurred_at`) ORDER BY (`occurred_at`, `purchase_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`shop_purchases` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_shop_purchases` REFRESH EVERY 5 MINUTE OFFSET 150 SECOND TO `vatican_bi`.`shop_purchases_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`shop_purchases` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.`event_delivery` SQL SECURITY DEFINER AS SELECT event_id, occurred_at, received_at, toDate(received_at) AS day,
            event_name, source, schema_version,
            dateDiff('millisecond', occurred_at, received_at) / 1000.0 AS lag_seconds
        FROM `vatican_analytics`.raw_game_events FINAL
        WHERE source IN ('game_backend', 'shop') AND event_name IN (
            'run.completed', 'xp.granted', 'player.level_up',
            'level_gift.claimed', 'case.opened', 'shop.purchase_confirmed');

CREATE TABLE IF NOT EXISTS `vatican_bi`.`event_delivery_snapshot` ENGINE = MergeTree PARTITION BY toYYYYMM(`received_at`) ORDER BY (`received_at`, `event_id`) SETTINGS index_granularity = 2048 AS SELECT * FROM `vatican_bi`.`event_delivery` LIMIT 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS `vatican_bi`.`refresh_event_delivery` REFRESH EVERY 5 MINUTE OFFSET 180 SECOND TO `vatican_bi`.`event_delivery_snapshot` SQL SECURITY DEFINER AS SELECT * FROM `vatican_bi`.`event_delivery` SETTINGS max_threads = 2, max_execution_time = 120, max_memory_usage = 536870912;

CREATE OR REPLACE VIEW `vatican_bi`.refresh_status SQL SECURITY DEFINER AS SELECT *,
        transform(health_code,
            ['missing_job','refresh_failed','refresh_stopped','dependency_wait','never_succeeded','stale','unknown_state','ok'],
            ['Нет задачи обновления','Ошибка обновления','Обновление остановлено','Ожидание источников',
             'Нет успешного обновления','Данные устарели','Неизвестное состояние задачи','Актуально'], 'Неизвестное состояние') AS health,
        transform(health_code,
            ['missing_job','refresh_failed','refresh_stopped','dependency_wait','never_succeeded','stale','unknown_state','ok'],
            ['Администратору: повторить инициализацию BI.',
             'Проверьте журнал ClickHouse и повторите пересчёт.',
             'Администратору: запустить задачу обновления и дождаться успеха.',
             'Проверьте доступность зависимых витрин.',
             'Дождитесь первого успешного пересчёта.',
             'Проверьте расписание и последнюю попытку.',
             'Администратору: проверить состояние задачи.',
             'Действий не требуется.'], 'Администратору: проверить состояние задачи.') AS recovery_hint
        FROM (SELECT transform(expected, ['refresh_runs', 'refresh_xp', 'refresh_level_ups', 'refresh_level_gifts', 'refresh_case_openings', 'refresh_shop_purchases', 'refresh_event_delivery'], ['Подтверждённые забеги', 'Начисления XP', 'Переходы уровней', 'Полученные подарки', 'Завершённые кейсы', 'Покупки за престиж', 'Доставка событий'], expected) AS dataset,
            multiIf(ifNull(job_exists, 0) = 0, 'missing_job',
                ifNull(exception, '') != '', 'refresh_failed',
                ifNull(status, '') IN ('Disabled','Stopped'), 'refresh_stopped',
                ifNull(status, '') IN ('WaitingForDependencies','MissingDependencies'), 'dependency_wait',
                ifNull(status, '') NOT IN ('Scheduled','Running','RunningOnAnotherReplica','Scheduling'), 'unknown_state',
                isNull(last_success_time), 'never_succeeded',
                dateDiff('second', last_success_time, now()) > 600, 'stale', 'ok') AS health_code,
            last_success_time AS last_success,
            dateDiff('second', last_success_time, now()) AS age_seconds,
            next_refresh_time AS next_refresh, written_rows AS rows_written,
            last_success_duration_ms AS duration_ms, status AS refresh_state,
            last_refresh_time AS last_attempt
        FROM (SELECT arrayJoin(['refresh_runs', 'refresh_xp', 'refresh_level_ups', 'refresh_level_gifts', 'refresh_case_openings', 'refresh_shop_purchases', 'refresh_event_delivery']) AS expected) AS expected_jobs
        LEFT JOIN (SELECT *, toUInt8(1) AS job_exists FROM (SELECT * FROM system.view_refreshes WHERE database = 'vatican_bi')) AS jobs
            ON jobs.view = expected_jobs.expected);
